-- Series FM-10 (metal-seated high-pressure 3-piece, quote-only Price NULL). Run from file (SSMS). Self-cleaning on re-run.
IF NOT EXISTS (SELECT 1 FROM Categories WHERE Name = N'Series FM-10')
    INSERT INTO Categories (Name, Description, BodyMaterial, SeatMaterial, Design, Approvals, KeyFeatures)
    VALUES (N'Series FM-10',
        N'The Mars Series FM-10 is a 3-piece metal-seated high-pressure ball valve rated 3600 PSI (threaded/weld) and ANSI Class 1500 (flanged), full or reduced port, in sizes 1/2" to 2". CF8M or WCB body with SS316+Stellite seats, a CF8M+hard-chrome ball and a 17-4PH stem. Conforms to ASME B16.34.',
        N'CF8M / WCB', N'SS316 + Stellite', N'Three Piece, Metal Seated, Full & Reduced Port, High Pressure', N'ASME B16.34',
        N'3-piece metal seated high pressure design
Full port & reduced port
Pressure: 3600 PSI / ANSI #1500
Ends: Threaded, Butt Weld, Socket Weld, Flanged (ANSI #1500)
Body: CF8M, WCB
Seats: SS316 + Stellite
Ball: CF8M + Hard Chrome
Stem: 17-4PH
Conforms to ASME B16.34
Size 1/2" to 2"');

DECLARE @SeriesName nvarchar(100) = N'Series FM-10';
DECLARE @CategoryId int = (SELECT CategoryId FROM Categories WHERE Name = @SeriesName);

-- Idempotent: clear any prior rows for this series so re-running always yields a clean set.
DELETE FROM ProductFilterValues WHERE CategoryId = @CategoryId;
DELETE FROM CatalogProducts WHERE CategoryId = @CategoryId;
DELETE FROM CategoryFilters WHERE CategoryId = @CategoryId;

INSERT INTO Filters (Name) SELECT v.Name FROM (VALUES (N'Ends'),(N'Size'),(N'Port'),(N'Body')) AS v(Name)
WHERE NOT EXISTS (SELECT 1 FROM Filters f WHERE f.Name = v.Name);

INSERT INTO CategoryFilters (CategoryId, FilterId, SortOrder)
SELECT @CategoryId, f.FilterId, v.SortOrder FROM (VALUES (N'Ends',0),(N'Size',1),(N'Port',2),(N'Body',3)) AS v(FilterName, SortOrder)
JOIN Filters f ON f.Name = v.FilterName WHERE NOT EXISTS (SELECT 1 FROM CategoryFilters cf WHERE cf.CategoryId=@CategoryId AND cf.FilterId=f.FilterId);

